   145	  const versionDescription = getArg('--version-description') ?? undefined;
   146	
   147	  const client = contentfulManagement.createClient(
   148	    { accessToken: process.env.CONTENTFUL_MANAGEMENT_TOKEN },
   149	    { type: 'plain' },
   150	  );
   151	
   152	  const defsDir = path.join(__dirname, 'content-types');
   153	  const files = fs
   154	    .readdirSync(defsDir)
   155	    .filter((f) => f.endsWith('.js'))
   156	    .sort();
   157	
   158	  if (!files.length) {
   159	    console.log('No content type definitions found in scripts/contentful/content-types/');
   160	    return;
   161	  }
   162	
   163	  const defs = files.map((file) => {
   164	    const def = /** @type {ContentTypeDefinition} */ (require(path.join(defsDir, file)));
   165	    console.log(`→ Including "${def.id}" (${file})`);
   166	    return def;
   167	  });
   168	
   169	  const contentTypeTemplates = defs.map(buildContentTypeTemplate);
   170	  const editorInterfaceTemplates = defs.map(buildEditorInterfaceTemplate).filter(Boolean);
   171	
   172	  const { items: existing } = await client.environmentTemplate.getMany({
   173	    organizationId,
   174	    query: { limit: 100 },
   175	  });
   176	  const found = existing.find((t) => t.name === TEMPLATE_NAME);
   177	
   178	  if (!found) {
