   100	/**
   101	 * Fetches and renders the `zimmermann` Experience entry matching `slug` (the single Experience
   102	 * Type covering every page on this site). Shared by pages/experience/index.tsx (`/:slug`) and
   103	 * pages/home/index.tsx (`/`, slug `''`) so both stay wired to the same experienceTypeId and the
   104	 * same preview/Studio-canvas handling.
   105	 */
   106	export const ExperienceBySlug = ({ slug, isPreview = false, isEditorCanvas = false }: ExperienceBySlugProps) => {
   107	  const { locale: siteLocale } = useMultiSite() as { locale?: { id: string } };
   108	  const locale = siteLocale?.id || CONTENTFUL_FALLBACK_LOCALE;
   109	  const { res } = useServerContext();
   110	  // Preview requests use the CPA host+token only when a token is configured; otherwise the page
   111	  // renders in normal delivery mode. A preview request WITHOUT a token is handled explicitly
   112	  // below (404 + noindex) — it never silently falls back to delivery.
   113	  const {
   114	    client,
   115	    previewUnavailable,
   116	    isPreview: effectivePreview,
   117	  } = useContentfulClient({
   118	    preview: isPreview,
   119	  });
   120	
   121	  // @contentful/experiences-sdk-react's useFetchBySlug (called inside ExperienceFetch) branches its
   122	  // initial canvas-mode state on `typeof window !== 'undefined'`, which differs between the SSR pass
   123	  // and the client's first hydration pass when this page loads inside Contentful Studio's Experience
   124	  // Builder canvas iframe — a structural hydration mismatch (React errors #418/#423) that discards the
   125	  // whole render. Delaying ExperienceFetch's mount until after hydration means the server and the
   126	  // client's first paint both render the same Spinner placeholder below, so there's nothing to
   127	  // mismatch — useFetchBySlug then only ever runs in a pure client-side render pass.
   128	  //
   129	  // Only applied when `isEditorCanvas` (the `expEditorMode` query param Contentful Studio's canvas
   130	  // appends to its iframe URL — visible server-side via the query string, unlike `window`/iframe
   131	  // detection) is set — a normal storefront request never sets it, so it keeps rendering the real
   132	  // experience content in the initial SSR response as before, per the perf budget in AGENTS.md.
   133	  const [mounted, setMounted] = useState(false);
   134	  useEffect(() => {
   135	    if (isEditorCanvas) {
   136	      setMounted(true);
   137	    }
   138	  }, [isEditorCanvas]);
