   140	  // Preview requested but no CPA token (the non-prod gate): fail explicitly with a 404 and
   141	  // noindex, mirroring the /preview route, so a `?preview` URL is never an indexable 200 on prod.
   142	  if (previewUnavailable) {
   143	    if (res) {
   144	      res.status(404);
   145	    }
   146	    return (
   147	      <>
   148	        <Seo noIndex />
   149	        <Box p={8}>
   150	          <Text color="red.500">Preview is not enabled in this environment.</Text>
   151	        </Box>
   152	      </>
   153	    );
   154	  }
   155	
   156	  if (!client) {
   157	    // Contentful config missing = server misconfiguration, not a missing page: 500 (not 404),
   158	    // + noindex so the error state is never indexed if it ever surfaces in production.
   159	    if (res) {
   160	      res.status(500);
   161	    }
   162	    return (
   163	      <>
   164	        <Seo noIndex />
   165	        <Box p={8}>
   166	          <Text color="red.500">Contentful configuration is missing — cannot render this page.</Text>
   167	        </Box>
   168	      </>
   169	    );
   170	  }
   171	
   172	  if (isEditorCanvas && !mounted) {
   173	    return (
   174	      <Box p={8} display="flex" justifyContent="center">
   175	        <Spinner size="xl" />
   176	      </Box>
   177	    );
   178	  }
   179	
   180	  return <ExperienceFetch client={client} slug={slug} locale={locale} isPreview={effectivePreview} />;
   181	};

