   117	/**
   118	 * Fetches a single Contentful entry by its sys.id and resolves linked assets/entries.
   119	 *
   120	 * @param entryId - Contentful entry sys.id to fetch.
   121	 * @param preview - When true, uses the Preview API (draft content). Defaults to false.
   122	 * @param locale - Optional locale string (e.g. 'en-AU'). Omit to use Contentful's default.
   123	 * @returns `{ data, isLoading, error }` where `data` is typed as `T | null`.
   124	 */
   125	export const useContentfulEntry = <T>(entryId: string, preview = false, locale?: string) => {
   126	  const [data, setData] = useState<T | null>(null);
   127	  const [isLoading, setIsLoading] = useState(true);
   128	  const [error, setError] = useState<Error | null>(null);
   129	
   130	  useEffect(() => {
   131	    const controller = new AbortController();
   132	
   133	    // Reset rather than leaving the previous request's data/error in place — without this,
   134	    // a locale change on an already-mounted consumer (e.g. UiCopyProvider) would keep
   135	    // rendering the old locale's content until the new fetch resolves.
   136	    setIsLoading(true);
   137	    setError(null);
   138	    setData(null);
   139	
   140	    const fetchEntry = async () => {
   141	      try {
   142	        const config = getValidatedContentfulConfig();
   143	        // Search endpoint with sys.id, so include=2 still resolves linked assets.
   144	        const url = buildContentfulUrl(`sys.id=${entryId}`, config, preview, locale);
   145	        const response = await fetch(url, { signal: controller.signal });
   146	
   147	        if (!response.ok) {
   148	          throw new Error(`Contentful API error: ${response.status}`);
   149	        }
   150	
   151	        const result: ContentfulEntriesResponse = await response.json();
   152	        const item = result.items[0];
   153	        if (!item) {
   154	          throw new Error(`Entry ${entryId} not found`);
   155	        }
   156	        setData(resolveLinkedAssets(item, result.includes) as T);
   157	      } catch (err) {
   158	        if (err instanceof DOMException && err.name === 'AbortError') return;
   159	        setError(err instanceof Error ? err : new Error('Unknown error'));
   160	      } finally {
   161	        // Guards against the superseded request's own `finally` running after this effect
   162	        // has already started a new one (e.g. deps changed before the prior fetch settled) —
   163	        // controller.signal.aborted flips synchronously the instant cleanup calls abort(),
   164	        // so by the time an aborted request's finally runs, it can tell it's no longer current.
   165	        if (!controller.signal.aborted) setIsLoading(false);
   166	      }
   167	    };
   168	
   169	    void fetchEntry();
   170	    return () => controller.abort();
   171	  }, [entryId, preview, locale]);
   172	
   173	  return { data, isLoading, error };
   174	};
   175	
   176	/**
   177	 * Fetches all Contentful entries of a given content type and resolves their linked assets/entries.
   178	 *
   179	 * @param contentType - Contentful content type ID (e.g. 'iconAndText').
   180	 * @param preview - When true, uses the Preview API (draft content). Defaults to false.
   181	 * @param locale - Optional locale string (e.g. 'en-AU'). Omit to use Contentful's default.
   182	 * @param filter - Optional additional Contentful query filter appended to the request
   183	 *   (e.g. `'fields.placement=benefits'`). Follows Contentful's Search Parameters syntax.
   184	 * @param enabled - When false, skips the fetch entirely (useful for conditional fetching).
   185	 * @returns `{ data, isLoading, error }` where `data` is typed as `T[] | null`.
   186	 */
   187	export const useContentfulEntries = <T>(
   188	  contentType: string,
   189	  preview = false,
   190	  locale?: string,
   191	  filter?: string,
   192	  enabled = true,
   193	  include = 2,
   194	) => {
   195	  const [data, setData] = useState<T[] | null>(null);
   196	  const [isLoading, setIsLoading] = useState(true);
   197	  const [error, setError] = useState<Error | null>(null);
   198	
   199	  useEffect(() => {
   200	    if (!enabled) {
   201	      setData(null);
   202	      setError(null);
   203	      setIsLoading(false);
   204	      return;
   205	    }
   206	
   207	    const controller = new AbortController();
   208	
   209	    // Reset rather than leaving the previous request's data/error in place — without this,
   210	    // a locale change on an already-mounted consumer (e.g. UiCopyProvider) would keep
   211	    // rendering the old locale's content until the new fetch resolves.
   212	    setIsLoading(true);
   213	    setError(null);
   214	    setData(null);
   215	
   216	    const fetchEntries = async () => {
   217	      try {
   218	        const config = getValidatedContentfulConfig();
   219	        const query = filter ? `content_type=${contentType}&${filter}` : `content_type=${contentType}`;
   220	        const url = buildContentfulUrl(query, config, preview, locale, include);
   221	        const response = await fetch(url, { signal: controller.signal });
   222	
   223	        if (!response.ok) {
   224	          throw new Error(`Contentful API error: ${response.status}`);
   225	        }
   226	
   227	        const result: ContentfulEntriesResponse = await response.json();
   228	        const resolvedItems = result.items.map((item) => resolveLinkedAssets(item, result.includes));
   229	        setData(resolvedItems as T[]);
   230	      } catch (err) {
   231	        if (err instanceof DOMException && err.name === 'AbortError') return;
   232	        setError(err instanceof Error ? err : new Error('Unknown error'));
   233	      } finally {
   234	        // See useContentfulEntry's identical guard above for why this check is needed.
   235	        if (!controller.signal.aborted) setIsLoading(false);
   236	      }
   237	    };
   238	
   239	    void fetchEntries();
   240	    return () => controller.abort();
   241	  }, [contentType, preview, locale, filter, enabled, include]);
   242	
   243	  return { data, isLoading, error };
   244	};

