 *
 * Uses `@tanstack/react-query`'s `useQuery` rather than the footer's raw `useEffect`/
 * `useState` — the app already mounts a `QueryClientProvider` for every page via
 * `withReactQuery(AppConfig, ...)` in `_app-config`, so this needs no provider of its own.
 *
 * @returns the current storefront's resolved header nav items, plus query status flags.
 *   `items` is `undefined` while loading, on fetch failure, or when no entry resolves for
 *   this region — callers should treat that the same as "nothing to render yet," matching
 *   FooterContainer's "renders nothing" behaviour on an unresolved fetch.
 */
export const useHeaderNav = (): UseHeaderNavResult => {
  const { site, locale: siteLocale } = useMultiSite() as MultiSiteResult;
  const locale = siteLocale?.id ?? CONTENTFUL_FALLBACK_LOCALE;
  const { client } = useContentfulClient();

  const { data, isLoading, isError } = useQuery({
    queryKey: [HEADER_NAV_QUERY_KEY, site.id, locale],
    queryFn: async () => {
      // Guaranteed non-null: `enabled: !!client` below means this only runs once a client
      // exists, but TypeScript can't see that gate from inside the closure.
      // `useContentfulClient` types the client as `ContentfulClientApi<any>` for the
      // Experiences SDK's benefit — with `any` chain modifiers, `EntriesQueries`'s
      // `locale` field resolves out of the type entirely (see its `WITH_ALL_LOCALES`
      // conditional), so narrow back to the real default (`undefined`) modifiers here.
      const entries = await (client as ContentfulClientApi<undefined>)!.getEntries({
        content_type: CONTENT_TYPE_IDS.headerNavigation,
        include: HEADER_NAV_INCLUDE_DEPTH,
        locale,
      });
      // The contentful SDK client is loosely typed (see useContentfulClient.ts) —
      // HeaderNavigationEntry mirrors the exact nested-resolved shape `include: 4`
      // produces for this content model.
      return entries.items as unknown as HeaderNavigationEntry[];
    },
    enabled: !!client,
  });

  const resolved = data ? pickMostSpecificByRegion<HeaderNavigationEntry>(data, site.id) : undefined;
  const items = isLoading
    ? undefined
    : resolved

