const renderTextNode = (node: ContentfulRichTextNode, i: number): React.ReactNode => {
  switch (node.nodeType) {
    case 'heading-1':
    case 'heading-2':
    case 'heading-3':
    case 'heading-4':
    case 'heading-5':
    case 'heading-6':
      return (
        <chakra.h2 key={i} textStyle="productNames" color="var(--zimm-color-text-default)" margin={0}>
          {extractText(node)}
        </chakra.h2>
      );
    case 'paragraph': {
      const text = extractText(node);
      if (!text.trim()) return null;
      return (
        <chakra.p key={i} textStyle="caption" color="var(--zimm-color-text-default)" margin={0}>
          {(node.content ?? []).map((inline, j) => {
            if (inline.nodeType !== 'text') return null;
            let child: React.ReactNode = inline.value ?? '';
            if (inline.marks?.some((m) => m.type === 'bold')) child = <strong key={j}>{child}</strong>;
            if (inline.marks?.some((m) => m.type === 'italic')) child = <em key={j}>{child}</em>;
            return <React.Fragment key={j}>{child}</React.Fragment>;
          })}
        </chakra.p>
      );
    }
    default:
      return null;
  }
};
